// <auto-imports> — generated by wire.mjs, do not edit by hand
import { MODULE_ID } from "./constants.js";
import { routeActorPortrait, routeAssetPath } from "./sheet.js";
import { waitForPresentationFrames } from "./viewport.js";
// </auto-imports>
// Actor / combat / token placement + movement handlers — extracted from mobile-bridge.js.

export function listOwnedActors(user) {
  return game.actors
    .filter((actor) => actor.type === "character" && actor.testUserPermission(user, "OWNER"))
    .map((actor) => ({
      actorId: actor.id,
      name: actor.name,
      type: actor.type,
      img: routeActorPortrait(actor),
      // Foundry's own record of when the actor was made. Zero where the world
      // predates it being kept, which the phone treats as "unknown" rather
      // than as the beginning of time.
      createdTime: Number(actor._stats?.createdTime) || 0
    }));
}

export function getOwnedActor(user, actorId) {
  if (!actorId) throw new Error("actorId is required");
  const actor = game.actors.get(actorId);
  if (!actor) throw new Error("Actor not found");
  if (!actor.testUserPermission(user, "OWNER")) throw new Error("User does not own actor");
  return actor;
}

/**
 * Token documents on a scene that represent this actor (by actorId).
 * We do not use actor.getActiveTokens() here: core Foundry compares token references with
 * canvas.scene.tokens.get(id), and _dependentTokens can hold a different object instance,
 * so getActiveTokens() often returns [] even when the token is on the map.
 */
export function tokenDocumentsForActorOnScene(actor, scene) {
  if (!scene?.tokens) return [];
  if (actor.isToken) {
    const t = actor.token;
    return t?.parent?.id === scene.id ? [t] : [];
  }
  const id = actor.id;
  const out = [];
  const contents = scene.tokens.contents ?? [...scene.tokens.values()];
  for (const token of contents) {
    if (token.actorId === id) out.push(token);
  }
  return out;
}

/**
 * Non-pseudo status conditions the player may toggle on their own actor, with
 * current active state. Mirrors the character sheet's own condition picker
 * (`ActorSheet5eCharacter#_prepareEffectsContext`): `CONFIG.DND5E.conditionTypes`,
 * excluding entries flagged `pseudo` (e.g. "concentrating", which is derived, not
 * manually assignable). `actor.statuses` is core's own set of currently-applied
 * status ids, kept in sync by `applyActiveEffects`.
 */
export function actorConditionList(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const conditionTypes = CONFIG.DND5E?.conditionTypes ?? {};
  const conditions = [];
  for (const [id, cfg] of Object.entries(conditionTypes)) {
    if (!cfg || cfg.pseudo) continue;
    conditions.push({
      id,
      name: cfg.name ? game.i18n.localize(cfg.name) : id,
      img: routeAssetPath(cfg.img ?? null),
      active: actor.statuses?.has(id) ?? false
    });
  }
  return { actorId: actor.id, conditions };
}

/**
 * Adds or removes one status condition on the acting user's own actor. Uses
 * the same public API core uses for the token HUD's status-effect icons
 * (`Actor#toggleStatusEffect`, overridden in dnd5e's Actor5e to also clear
 * other members of the status's exclusive group) so this behaves exactly like
 * a player clicking their own token's status icon in the browser.
 */
export async function actorConditionToggle(user, actorId, statusId, active) {
  const actor = getOwnedActor(user, actorId);
  const id = String(statusId ?? "").trim();
  if (!id) throw new Error("statusId is required");
  const conditionTypes = CONFIG.DND5E?.conditionTypes ?? {};
  const cfg = conditionTypes[id];
  if (!cfg || cfg.pseudo) throw new Error("Unknown condition");
  const desired = active !== false;
  await actor.toggleStatusEffect(id, { active: desired });
  return { accepted: true, actorId: actor.id, statusId: id, active: desired };
}

/**
 * Token "movement action" modes (walk/fly/burrow/swim/climb/…) available on
 * this Foundry version, with the acting user's own token's current mode.
 * `CONFIG.Token.movement.actions` is a Foundry v13+ concept (the per-token
 * movement-action schema field does not exist on v12); `supported: false`
 * with an empty `modes` list tells the phone to hide the control there.
 * Filtering mirrors the core Token HUD's own action menu
 * (`TokenHUD#_getMovementActionChoices`): `config.canSelect(tokenDocument)`,
 * always keeping the token's current mode even if it would otherwise be
 * filtered (e.g. a mode that stopped applying after a condition changed).
 */
export function actorMovementModeList(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const actions = CONFIG.Token?.movement?.actions;
  if (!actions) return { actorId: actor.id, supported: false, modes: [], current: null };
  const scene = canvas?.ready ? canvas.scene : null;
  const tokenDocs = scene ? tokenDocumentsForActorOnScene(actor, scene) : [];
  const td = tokenDocs[0] ?? actor.prototypeToken ?? null;
  const defaultAction = CONFIG.Token.movement.defaultAction ?? "walk";
  const current = td?.movementAction ?? defaultAction;
  const modes = Object.entries(actions)
    .filter(([id, cfg]) => {
      if (!cfg) return false;
      if (id === current) return true;
      if (typeof cfg.canSelect !== "function") return true;
      try {
        return !!cfg.canSelect(td);
      } catch {
        return true;
      }
    })
    .sort(([, a], [, b]) => (a.order ?? 0) - (b.order ?? 0))
    .map(([id, cfg]) => ({
      id,
      label: cfg.label ? game.i18n.localize(cfg.label) : id,
      icon: cfg.icon ?? null
    }));
  return { actorId: actor.id, supported: true, modes, current, defaultAction };
}

/**
 * Sets the movement mode on every scene token representing this actor (there
 * is normally exactly one — see `tokenDocumentsForActorOnScene`), and on the
 * actor's prototype token so a token placed later starts in the same mode.
 * Same v13+ requirement as `actorMovementModeList` above.
 */
export async function actorTokenMovementModeSet(user, actorId, mode) {
  const actor = getOwnedActor(user, actorId);
  const actions = CONFIG.Token?.movement?.actions;
  if (!actions) throw new Error("Movement modes are not available on this Foundry version");
  const id = String(mode ?? "").trim();
  if (!id || !(id in actions)) throw new Error("Unknown movement mode");
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  const tokenDocs = tokenDocumentsForActorOnScene(actor, canvas.scene);
  if (!tokenDocs.length) throw new Error("No token on scene");
  for (const td of tokenDocs) {
    await td.update({ movementAction: id });
  }
  await actor.update({ "prototypeToken.movementAction": id });
  return { accepted: true, actorId: actor.id, mode: id };
}

/**
 * Placeable for a TokenDocument on the current canvas.
 * Prefer document.object; fall back to the tokens layer (object can be null briefly).
 */
export function resolveTokenPlaceable(tokenDoc) {
  if (!tokenDoc) return null;
  return (
    tokenDoc.object
    ?? canvas.tokens?.get?.(tokenDoc.id)
    ?? canvas.tokens?.placeables?.find?.(
      (t) => t.id === tokenDoc.id || t.document?.id === tokenDoc.id
    )
    ?? null
  );
}

/**
 * Finds a started combat that includes this actor. Prefers `game.combat`
 * (active combat on the current scene of the executing client) when it
 * contains the actor, otherwise scans all combats. This matters because the
 * GM client may be viewing a different scene than where the mobile player's
 * combat is running, in which case `game.combat` would be null or unrelated.
 */
export function findCombatForActor(actor) {
  const preferred = game.combat;
  const matchesActor = (c) => {
    if (!c?.started) return false;
    const combatants = c.combatants?.contents ?? [...(c.combatants?.values?.() ?? [])];
    return combatants.some((cb) => (cb.actor?.id ?? cb.actorId) === actor.id);
  };
  if (matchesActor(preferred)) return preferred;
  const all = game.combats?.contents ?? [...(game.combats?.values?.() ?? [])];
  for (const c of all) {
    if (matchesActor(c)) return c;
  }
  return null;
}

export function actorSceneIdsForCombat(actor) {
  const ids = new Set();
  const scene = canvas?.scene ?? game.scenes?.current;
  if (scene && tokenDocumentsForActorOnScene(actor, scene).length) {
    ids.add(scene.id);
  }
  try {
    for (const token of actor.getActiveTokens?.() ?? []) {
      const sid = token.document?.parent?.id ?? token.scene?.id;
      if (sid) ids.add(sid);
    }
  } catch (_) { /* actor may not expose tokens on this client */ }
  return ids;
}

/** Started combat for initiative: existing combatant, same scene as token, or any started combat. */
export function findStartedCombatForInitiative(actor) {
  const existing = findCombatForActor(actor);
  if (existing) return existing;

  const sceneIds = actorSceneIdsForCombat(actor);
  const all = game.combats?.contents ?? [...(game.combats?.values?.() ?? [])];
  for (const c of all) {
    if (!c?.started) continue;
    const sid = c.scene?.id ?? c.scene;
    if (sceneIds.size && sid && sceneIds.has(sid)) return c;
  }
  for (const c of all) {
    if (c?.started) return c;
  }
  return null;
}

export async function activateCombatForRoll(combat) {
  if (!combat?.started) return false;
  if (game.combat?.id === combat.id && game.combat.started) return true;
  if (typeof combat.activate === "function") {
    await combat.activate();
  }
  return !!(game.combat?.id === combat.id && game.combat.started);
}

/**
 * The turn order, as Foundry's own tracker shows it to this user.
 *
 * Everything the GM has not marked hidden travels, creatures the character
 * cannot currently see included — that is what the browser puts in front of the
 * same player, and an order with gaps in it would answer "who is next" wrongly.
 * Hidden combatants are dropped unless the user owns them, which is
 * Combatant#visible asked on behalf of the phone rather than of this tab.
 */
export function combatTurnsForUser(combat, user, actor) {
  const scene = canvas?.scene ?? game.scenes?.current ?? null;
  const ownTokenIds = new Set(
    scene ? tokenDocumentsForActorOnScene(actor, scene).map((td) => td.id) : []
  );
  const list = combat.turns ?? [];
  const active = combat.turn ?? -1;
  const turns = [];
  for (let i = 0; i < list.length; i++) {
    const c = list[i];
    if (!c) continue;
    if (c.hidden && !c.testUserPermission?.(user, "OWNER")) continue;
    const tokenDoc = c.token ?? null;
    const isSelf = tokenDoc
      ? ownTokenIds.has(tokenDoc.id)
      : (c.actorId && c.actorId === actor.id);
    const disp = tokenDoc?.disposition;
    let side = "neutral";
    if (isSelf) side = "self";
    else if (disp === CONST.TOKEN_DISPOSITIONS.FRIENDLY) side = "friendly";
    else if (disp === CONST.TOKEN_DISPOSITIONS.HOSTILE) side = "hostile";
    turns.push({
      combatantId: c.id,
      tokenId: tokenDoc?.id ?? null,
      name: c.name ?? "?",
      img: c.img ?? tokenDoc?.texture?.src ?? null,
      side,
      isSelf: !!isSelf,
      defeated: c.isDefeated === true,
      active: i === active
    });
  }
  return turns;
}

export function combatSnapshotForActor(actor, user = null) {
  const combat = findStartedCombatForInitiative(actor);
  if (!combat?.started) {
    return {
      encounterActive: false,
      actorsTurn: false,
      turnKey: null,
      round: null,
      turn: null,
      turns: []
    };
  }
  const round = combat.round ?? 0;
  const turn = combat.turn ?? 0;
  const turnKey = `${combat.id}:${round}:${turn}`;
  return {
    encounterActive: true,
    actorsTurn: isActorsCombatTurn(actor, combat),
    turnKey,
    round,
    turn,
    // Only where somebody is going to draw it: the placement payload asks about
    // one token, not about the whole encounter.
    turns: user ? combatTurnsForUser(combat, user, actor) : []
  };
}

export function isActorsCombatTurn(actor, combat) {
  const cur = combat.combatant;
  if (!cur) return false;
  const curActorId = cur.actor?.id ?? cur.actorId;
  if (!curActorId || curActorId !== actor.id) return false;
  const scene = canvas?.scene ?? game.scenes?.current;
  if (!scene) return true;
  const tokenDocs = tokenDocumentsForActorOnScene(actor, scene);
  if (tokenDocs.length <= 1) return true;
  const curTokenId = cur.token?.id;
  if (!curTokenId) return true;
  return tokenDocs.some((t) => t.id === curTokenId);
}

/**
 * Token on the canvas + grid cell (Foundry offset i,j). Gridless scenes report gridless: true.
 */
export function tokenPlacementForActor(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const combat = combatSnapshotForActor(actor);
  const current = game.scenes?.current;
  if (!canvas?.ready || !canvas.scene) {
    return {
      hasTokenOnScene: false,
      tokenCount: 0,
      reason: "canvas_not_ready",
      sceneName: current?.name ?? null,
      sceneId: current?.id ?? null,
      tokenId: null,
      gridless: false,
      gridType: "unknown",
      gridTypeId: null,
      gridI: null,
      gridJ: null,
      gridDistance: null,
      combat
    };
  }
  const scene = canvas.scene;
  const tokenDocs = tokenDocumentsForActorOnScene(actor, scene);
  const first = tokenDocs[0];
  if (!first) {
    return {
      hasTokenOnScene: false,
      tokenCount: 0,
      reason: "no_token",
      sceneName: scene.name ?? null,
      sceneId: scene.id ?? null,
      tokenId: null,
      gridless: false,
      gridType: detectGridType(canvas.grid, scene),
      gridTypeId: scene?.grid?.type ?? canvas?.grid?.type ?? null,
      gridI: null,
      gridJ: null,
      gridDistance: null,
      combat
    };
  }
  const grid = canvas.grid;
  const gridless = !grid || grid.isGridless;
  const gridTypeId = scene?.grid?.type ?? grid?.type ?? null;
  const gridType = detectGridType(grid, scene);
  let gridI = null;
  let gridJ = null;
  let gridDistance = null;
  if (!gridless) {
    const off = grid.getOffset({ x: first.x, y: first.y });
    gridI = off.i;
    gridJ = off.j;
    gridDistance =
      typeof grid.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;
  }
  return {
    hasTokenOnScene: true,
    // More than one is not an error here — the scene is allowed to hold two of
    // anything — but everything downstream picks the first and says nothing,
    // so the count travels and the phone can say which question it cannot
    // answer.
    tokenCount: tokenDocs.length,
    reason: gridless ? "gridless" : null,
    sceneName: scene.name ?? null,
    sceneId: scene.id ?? null,
    tokenId: first.id ?? null,
    gridless,
    gridType,
    gridTypeId,
    gridI,
    gridJ,
    gridDistance,
    elevation: first.elevation ?? 0,
    combat
  };
}

export function detectGridType(grid, scene) {
  const type = scene?.grid?.type ?? grid?.type;
  const T = CONST.GRID_TYPES;
  if (type === T.GRIDLESS) return "gridless";
  if (type === T.SQUARE) return "square";
  if (
    (type === T.HEXODDR) ||
    (type === T.HEXEVENR) ||
    (type === T.HEXODDQ) ||
    (type === T.HEXEVENQ)
  ) return "hex";
  return "unknown";
}

export function movementDirectionConstByKey(key) {
  const normalized = String(key ?? "").toLowerCase();
  const D = CONST.MOVEMENT_DIRECTIONS;
  switch (normalized) {
    case "up": return D.UP;
    case "down": return D.DOWN;
    case "left": return D.LEFT;
    case "right": return D.RIGHT;
    case "up_left": return D.UP_LEFT;
    case "up_right": return D.UP_RIGHT;
    case "down_left": return D.DOWN_LEFT;
    case "down_right": return D.DOWN_RIGHT;
    default: return undefined;
  }
}

/** Same dx/dy Foundry keyboard uses for Token#_getShiftedPosition. */
export function movementDeltaByKey(key) {
  switch (String(key ?? "").toLowerCase()) {
    case "up": return { dx: 0, dy: -1 };
    case "down": return { dx: 0, dy: 1 };
    case "left": return { dx: -1, dy: 0 };
    case "right": return { dx: 1, dy: 0 };
    case "up_left": return { dx: -1, dy: -1 };
    case "up_right": return { dx: 1, dy: -1 };
    case "down_left": return { dx: -1, dy: 1 };
    case "down_right": return { dx: 1, dy: 1 };
    default: return null;
  }
}

export function tokenStepTrace(...args) {
  console.log(`[${MODULE_ID}:token-step]`, ...args);
}

export function offsetsEqual(a, b) {
  return Number(a?.i) === Number(b?.i) && Number(a?.j) === Number(b?.j);
}

/** Chain getShiftedOffset to plan N cells in one compass direction. */
export function planTokenStepOffsets(grid, startOff, direction, steps) {
  const path = [];
  let off = { i: Number(startOff.i), j: Number(startOff.j) };
  for (let i = 0; i < steps; i++) {
    if (typeof grid.getShiftedOffset !== "function") break;
    const next = grid.getShiftedOffset(off, direction);
    if (offsetsEqual(next, off)) break;
    const step = { i: Number(next.i), j: Number(next.j) };
    path.push(step);
    off = step;
  }
  return path;
}

/**
 * Plan waypoints the same way Foundry keyboard movement does.
 * Avoid getTopLeftPoint→getSnappedPosition: on pointy hexes the top-left of a
 * west neighbor often snaps into the NW/NE hex, so a "left" path starts diagonal-up.
 */
export function planKeyboardStepWaypoints(td, grid, directionKey, steps) {
  const delta = movementDeltaByKey(directionKey);
  if (!delta) return null;
  const TokenClass = td.object?.constructor ?? globalThis.CONFIG?.Token?.objectClass;
  const shiftFn = TokenClass?._getShiftedPosition;
  if (typeof shiftFn !== "function") return null;

  const source = td._source ?? td;
  const elev = source.elevation ?? td.elevation ?? 0;
  let position = { x: source.x, y: source.y, elevation: elev };
  let snapped = td.getSnappedPosition({
    x: position.x,
    y: position.y,
    elevation: elev,
    width: source.width,
    height: source.height,
    shape: source.shape
  });

  const waypoints = [];
  const path = [];
  for (let i = 0; i < steps; i++) {
    const next = shiftFn.call(TokenClass, delta.dx, delta.dy, 0, position, snapped, grid);
    if (
      Number(next.x) === Number(position.x) &&
      Number(next.y) === Number(position.y) &&
      Number(next.elevation ?? position.elevation) === Number(position.elevation)
    ) {
      break;
    }
    const nextElev = next.elevation ?? position.elevation;
    waypoints.push({
      x: next.x,
      y: next.y,
      elevation: nextElev,
      action: td.object?._getKeyboardMovementAction?.() ?? td.movementAction,
      snapped: true,
      explicit: false,
      checkpoint: true
    });
    const off = grid.getOffset({ x: next.x, y: next.y });
    path.push({ i: Number(off.i), j: Number(off.j) });
    position = { x: next.x, y: next.y, elevation: nextElev };
    snapped = next;
  }
  return { waypoints, path };
}

export function waypointFromOffset(td, grid, offset, elev) {
  const source = td._source ?? td;
  // Snap from hex center — top-left of a pointy hex is outside the cell and
  // often resolves to a diagonal neighbor.
  const center =
    typeof grid.getCenterPoint === "function"
      ? grid.getCenterPoint(offset)
      : grid.getTopLeftPoint(offset);
  const snapped = td.getSnappedPosition({
    x: center.x,
    y: center.y,
    elevation: elev,
    width: source.width,
    height: source.height,
    shape: source.shape
  });
  return {
    x: snapped.x,
    y: snapped.y,
    elevation: snapped.elevation ?? elev,
    action: td.object?._getKeyboardMovementAction?.() ?? td.movementAction,
    snapped: true,
    explicit: false,
    checkpoint: true
  };
}

/**
 * Fallback single-step waypoint when getShiftedOffset is unavailable (legacy).
 * Prefer offset math on hex — pixel bias + lagged td.x/y caused multi-step
 * moves to stop after 1 cell even with a clear path.
 */
export function computeNextTokenStepWaypoint(td, grid, direction) {
  const source = td._source ?? td;
  const startOff = grid.getOffset({ x: td.x, y: td.y });
  const elev = source.elevation ?? td.elevation ?? 0;

  if (typeof grid.getShiftedOffset === "function") {
    const nextOff = grid.getShiftedOffset(startOff, direction);
    if (offsetsEqual(nextOff, startOff)) {
      return { startOff, nextOff, waypoint: null, reason: "offset_unchanged" };
    }
    return {
      startOff,
      nextOff,
      waypoint: waypointFromOffset(td, grid, nextOff, elev),
      reason: "offset"
    };
  }

  const snapped = td.getSnappedPosition({
    x: source.x,
    y: source.y,
    elevation: elev,
    width: source.width,
    height: source.height,
    shape: source.shape
  });
  let biasX = 0;
  let biasY = 0;
  if (grid.isHexagonal) {
    if (grid.columns) biasY = 1;
    else biasX = 1;
  }
  const shifted = grid.getShiftedPoint({
    x: snapped.x + biasX,
    y: snapped.y + biasY,
    elevation: snapped.elevation
  }, direction);
  const waypoint = {
    x: Math.round(shifted.x - biasX),
    y: Math.round(shifted.y - biasY),
    elevation: snapped.elevation,
    action: td.object?._getKeyboardMovementAction?.() ?? td.movementAction,
    snapped: true,
    explicit: false,
    checkpoint: true
  };
  const nextOff = grid.getOffset({ x: waypoint.x, y: waypoint.y });
  const same = offsetsEqual(nextOff, startOff);
  return {
    startOff,
    nextOff,
    waypoint: same ? null : waypoint,
    reason: same ? "point_unchanged" : "point"
  };
}

/** Prefer document source for hex offset — animated td.x/y near hex edges jitter. */
export function tokenOffset(td, grid) {
  const source = td._source ?? td;
  return grid.getOffset({ x: source.x, y: source.y });
}

export async function awaitTokenMovementProgress(td, grid, beforeOff, maxFrames = 45) {
  const tok = td.object;
  if (tok?.movementAnimationPromise) {
    try {
      await tok.movementAnimationPromise;
    } catch (_err) {
      // Animation may reject when interrupted; still re-read offset below.
    }
  }
  for (let n = 0; n < maxFrames; n++) {
    await waitForPresentationFrames(1);
    const off = tokenOffset(td, grid);
    if (!offsetsEqual(off, beforeOff)) {
      return { progressed: true, off, frames: n + 1 };
    }
  }
  const off = tokenOffset(td, grid);
  return { progressed: !offsetsEqual(off, beforeOff), off, frames: maxFrames };
}

export async function moveTokenOneGrid(user, actorId, directionKey, stepsRaw) {
  const actor = getOwnedActor(user, actorId);
  if (!canvas?.ready || !canvas.scene) throw new Error("Canvas not ready");
  const grid = canvas.grid;
  if (!grid || grid.isGridless) throw new Error("Scene has no square/hex grid");

  const scene = canvas.scene;
  const tokenDocs = tokenDocumentsForActorOnScene(actor, scene);
  const td = tokenDocs[0];
  if (!td) throw new Error("No token on scene");

  const key = String(directionKey ?? "").toLowerCase();
  const steps = Math.max(1, Math.min(Math.floor(Number(stepsRaw) || 1), 10));

  // Elevation change: elevate/descend shift elevation by one grid distance (typically 5 ft)
  if (key === "elevate" || key === "descend") {
    const gridDist = typeof grid.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;
    const delta = key === "elevate" ? gridDist : -gridDist;
    const current = td.elevation ?? 0;
    const newElevation = Math.max(0, current + delta);
    if (key === "descend" && newElevation === current) {
      const off = grid.getOffset({ x: td.x, y: td.y });
      return {
        gridI: off.i,
        gridJ: off.j,
        movementCost: 0,
        tokenId: td.id ?? null,
        elevation: current,
        moved: false,
        stepsRequested: 1,
        cellsMoved: 0
      };
    }
    await td.update({ elevation: newElevation });
    const off = grid.getOffset({ x: td.x, y: td.y });
    return {
      gridI: off.i,
      gridJ: off.j,
      movementCost: gridDist,
      tokenId: td.id ?? null,
      elevation: newElevation,
      moved: true,
      stepsRequested: 1,
      cellsMoved: 1
    };
  }

  const direction = movementDirectionConstByKey(key);
  if (direction === undefined) {
    throw new Error(
      "direction must be up, down, left, right, up_left, up_right, down_left, down_right, elevate, or descend"
    );
  }
  if (typeof td.getSnappedPosition !== "function") {
    throw new Error("Token document does not support getSnappedPosition");
  }

  const cellCost =
    typeof grid.distance === "number" && Number.isFinite(grid.distance) ? grid.distance : 5;
  const originOff = tokenOffset(td, grid);
  const elev = (td._source ?? td).elevation ?? td.elevation ?? 0;

  tokenStepTrace("start", {
    actorId,
    tokenId: td.id,
    direction: key,
    stepsRaw,
    stepsRequested: steps,
    hex: !!grid.isHexagonal,
    columns: !!grid.columns,
    even: !!grid.even,
    gridType: scene?.grid?.type ?? grid?.type ?? null,
    from: { i: originOff?.i, j: originOff?.j },
    xy: { x: (td._source ?? td).x, y: (td._source ?? td).y }
  });

  // Prefer one multi-waypoint move: Foundry constrains walls and we avoid
  // false "blocked" stops from reading lagged td.x/y between micro-steps.
  const keyboardPlan = planKeyboardStepWaypoints(td, grid, key, steps);
  if (keyboardPlan) {
    const { waypoints, path } = keyboardPlan;
    tokenStepTrace("planned keyboard path", {
      length: path.length,
      path,
      delta: movementDeltaByKey(key)
    });
    if (!waypoints.length) {
      return {
        gridI: originOff.i,
        gridJ: originOff.j,
        movementCost: 0,
        tokenId: td.id ?? null,
        elevation: td.elevation ?? 0,
        moved: false,
        stepsRequested: steps,
        cellsMoved: 0
      };
    }
    const beforeOff = originOff;
    const completed = await td.move(waypoints, { method: "keyboard", showRuler: false });
    const settle = await awaitTokenMovementProgress(td, grid, beforeOff, Math.max(60, steps * 20));
    const afterOff = settle.off;

    let reached = 0;
    for (let i = path.length - 1; i >= 0; i--) {
      if (offsetsEqual(afterOff, path[i])) {
        reached = i + 1;
        break;
      }
    }
    if (reached === 0 && (completed || settle.progressed)) {
      const di = Math.abs(Number(afterOff.i) - Number(beforeOff.i));
      const dj = Math.abs(Number(afterOff.j) - Number(beforeOff.j));
      reached = Math.max(1, Math.max(di, dj));
    }

    const moved = reached > 0 || settle.progressed || !!completed;
    const cells = moved ? Math.max(1, reached) : 0;
    tokenStepTrace("multi-waypoint done", {
      planned: path.length,
      reached: cells,
      completed: !!completed,
      settled: settle.progressed,
      settleFrames: settle.frames,
      beforeOff,
      afterOff,
      moved,
      via: "keyboard"
    });
    return {
      gridI: afterOff.i,
      gridJ: afterOff.j,
      movementCost: moved ? cells * cellCost : 0,
      tokenId: td.id ?? null,
      elevation: td.elevation ?? 0,
      moved,
      stepsRequested: steps,
      cellsMoved: cells
    };
  }

  if (typeof grid.getShiftedOffset === "function") {
    const path = planTokenStepOffsets(grid, originOff, direction, steps);
    tokenStepTrace("planned offset path", { length: path.length, path });
    if (!path.length) {
      return {
        gridI: originOff.i,
        gridJ: originOff.j,
        movementCost: 0,
        tokenId: td.id ?? null,
        elevation: td.elevation ?? 0,
        moved: false,
        stepsRequested: steps,
        cellsMoved: 0
      };
    }
    const waypoints = path.map((off) => waypointFromOffset(td, grid, off, elev));
    const beforeOff = originOff;
    const completed = await td.move(waypoints, { method: "keyboard", showRuler: false });
    const settle = await awaitTokenMovementProgress(td, grid, beforeOff, Math.max(60, steps * 20));
    const afterOff = settle.off;

    // Match farthest planned cell (scan from end — constrained moves stop early).
    let reached = 0;
    for (let i = path.length - 1; i >= 0; i--) {
      if (offsetsEqual(afterOff, path[i])) {
        reached = i + 1;
        break;
      }
    }
    if (reached === 0 && (completed || settle.progressed)) {
      // Constrained/odd hex landing — charge by offset delta as a lower bound.
      const di = Math.abs(Number(afterOff.i) - Number(beforeOff.i));
      const dj = Math.abs(Number(afterOff.j) - Number(beforeOff.j));
      reached = Math.max(1, Math.max(di, dj));
    }

    const moved = reached > 0 || settle.progressed || !!completed;
    const cells = moved ? Math.max(1, reached) : 0;
    tokenStepTrace("multi-waypoint done", {
      planned: path.length,
      reached: cells,
      completed: !!completed,
      settled: settle.progressed,
      settleFrames: settle.frames,
      beforeOff,
      afterOff,
      moved,
      via: "offset"
    });
    return {
      gridI: afterOff.i,
      gridJ: afterOff.j,
      movementCost: moved ? cells * cellCost : 0,
      tokenId: td.id ?? null,
      elevation: td.elevation ?? 0,
      moved,
      stepsRequested: steps,
      cellsMoved: cells
    };
  }

  // Legacy single-step loop (no getShiftedOffset).
  let totalCost = 0;
  let movedAny = false;
  let cellsMoved = 0;
  let lastOff = originOff;
  for (let i = 0; i < steps; i++) {
    const planned = computeNextTokenStepWaypoint(td, grid, direction);
    tokenStepTrace("step plan", {
      i,
      reason: planned.reason,
      startOff: planned.startOff,
      nextOff: planned.nextOff,
      waypoint: planned.waypoint
        ? { x: planned.waypoint.x, y: planned.waypoint.y }
        : null
    });
    if (!planned.waypoint) break;
    const beforeOff = tokenOffset(td, grid);
    await td.move(planned.waypoint, { method: "keyboard", showRuler: false });
    const settle = await awaitTokenMovementProgress(td, grid, beforeOff, 45);
    lastOff = settle.off;
    tokenStepTrace("step result", {
      i,
      beforeOff,
      afterOff: settle.off,
      progressed: settle.progressed,
      settleFrames: settle.frames
    });
    if (!settle.progressed) break;
    movedAny = true;
    cellsMoved += 1;
    totalCost += cellCost;
  }
  tokenStepTrace("done legacy", {
    cellsMoved,
    stepsRequested: steps,
    totalCost,
    from: originOff,
    to: lastOff,
    moved: movedAny
  });
  return {
    gridI: lastOff.i,
    gridJ: lastOff.j,
    movementCost: movedAny ? totalCost : 0,
    tokenId: td.id ?? null,
    elevation: td.elevation ?? 0,
    moved: movedAny,
    stepsRequested: steps,
    cellsMoved
  };
}

/** dnd5e v3: mod/save are numbers. v4: often { value, roll? } bonus fields. */
